public static int polinomioEuler(int n) {
    // Produce primos para n entre 0 y 39, pero falla en n = 40 y n = 41
    return n * n + n + 41;
}

public static int buscar(int[] T, int x) {
    int i = 0;
    while (i < T.length && T[i] != x) {
        i++;
    }
    if (i < T.length) {
        return i;
    } else {
        return -1;
    }
}

public static int factorial(int n) {
    if (n == 0 || n == 1) {
        return 1;
    } else {
        return n * factorial(n - 1);
    }
}

public static int binrec(int[] T, int ini, int fin, int x) {
    if (ini > fin) {
        return -1;
    }
    int mid = (ini + fin) / 2;
    if (x == T[mid]) {
        return mid;
    } else if (x < T[mid]) {
        return binrec(T, ini, mid - 1, x);
    } else {
        return binrec(T, mid + 1, fin, x);
    }
}

