public class SubsetSumVerifier {
    public static boolean verifyCandidate(int[] values, boolean[] selectedMask, int targetSum) {
        int accumulatedSum = 0;
        for (int index = 0; index < values.length; index++) {
            if (selectedMask[index]) {
                accumulatedSum += values[index];
            }
        }
        return accumulatedSum == targetSum;
    }
}

