def verify_subset_sum_candidate(values: list[int], selected_mask: list[bool], target_sum: int) -> bool:
    accumulated_sum = 0
    for index, value in enumerate(values):
        if selected_mask[index]:
            accumulated_sum += value
    return accumulated_sum == target_sum
